SELECT b.id, b.name, b.city, b.lat, b.lng, COALESCE(s.qty, 0)::int, s.updated_at FROM branches b LEFT JOIN (SELECT branch_id, sum(quantity_on_hand - quantity_reserved) AS qty, max(updated_at) AS updated_at FROM inventory_batches WHERE medication_id = $1 AND NOT is_recalled AND expiry_date > now() GROUP BY branch_id) s ON s.branch_id = b.id WHERE b.participating AND b.id <> $2 ORDER BY b.id
